using System;
using UnityEngine;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Workshop {
public sealed class WorkshopEffects:MonoBehaviour {
 FinchVehicle car;WorkshopBuild build;AudioSource source;WorkshopAudioVoice voice;GameObject soundRoot;AudioClip clip;Light flame;MeshRenderer flameVisual;Material flameMaterial;float previousLoad,cooldown;double phase,whistle;int rate;volatile float hz=30,boost,whine,slip,volume;int popSamples,popLength;volatile float popGain;public int PopCount{get;private set;}public float TurboGain=>boost;public float SuperGain=>whine;public float SquealGain=>slip;
 public void Configure(FinchVehicle vehicle,WorkshopBuild state){car=vehicle;build=state;if(source==null){rate=AudioSettings.outputSampleRate;car.GetComponent<FinchDrivingHUD>()?.UseExternalEngineAudio();soundRoot=new GameObject("Workshop audio | single source/filter");soundRoot.transform.SetParent(car.transform,false);source=soundRoot.AddComponent<AudioSource>();voice=soundRoot.AddComponent<WorkshopAudioVoice>();voice.rate=rate;source.loop=true;source.spatialBlend=0;source.dopplerLevel=0;clip=AudioClip.Create("Workshop actual-state synthetic engine",rate,1,rate,false);source.clip=clip;source.Play();var g=new GameObject("Exhaust flame | visual only");g.transform.SetParent(car.transform,false);g.transform.localPosition=new Vector3(-.5f,.36f,-2.08f);flame=g.AddComponent<Light>();flame.color=new Color(.4f,.65f,1);flame.range=1.7f;flame.enabled=false;var volume=GameObject.CreatePrimitive(PrimitiveType.Sphere);volume.name="Brief exhaust flame visual";volume.transform.SetParent(g.transform,false);volume.transform.localPosition=new Vector3(0,0,-.12f);volume.transform.localScale=new Vector3(.10f,.08f,.34f);volume.GetComponent<Collider>().enabled=false;Destroy(volume.GetComponent<Collider>());flameVisual=volume.GetComponent<MeshRenderer>();flameMaterial=new Material(Shader.Find("Standard"));flameMaterial.color=new Color(.35f,.65f,1);flameMaterial.EnableKeyword("_EMISSION");flameMaterial.SetColor("_EmissionColor",new Color(.6f,1.4f,3));flameVisual.sharedMaterial=flameMaterial;flameVisual.enabled=false;}car.GetComponent<FinchDrivingHUD>()?.UseExternalEngineAudio();}
 public static bool TurboAllowed(WorkshopBuild b,float pressure,float load,bool grounded)=>b.induction!="none"&&b.induction!="roots"&&grounded&&load>.02f&&pressure>0;
 public static bool PopAllowed(WorkshopBuild b,float rpm,float previous,float load,bool grounded)=>b.sound!="road"&&b.exhaustStage>0&&grounded&&rpm>2800&&previous>.35f&&load<.15f;
 void Update(){if(car==null||build==null)return;float load=car.Throttle*car.Engine.ClutchEngagement;bool grounded=car.GroundedWheels>0;hz=car.Engine.Rpm/30;volume=car.controlsLocked?.025f:.06f+.035f*load;boost=TurboAllowed(build,car.Engine.BoostBar,load,car.DrivenGroundedWheels>0)?Mathf.Clamp01(car.Engine.BoostBar)*load*.035f:0;whine=build.induction=="roots"&&grounded?load*car.Engine.Rpm/6500*.045f:0;
  float wheelSlip=0;foreach(var wheel in car.Wheels)if(wheel.GetGroundHit(out var hit))wheelSlip=Mathf.Max(wheelSlip,Mathf.Abs(hit.sidewaysSlip),Mathf.Abs(hit.forwardSlip));slip=grounded&&(car.SpeedKph>8||car.IsBurningOut)?Mathf.InverseLerp(.15f,.7f,wheelSlip)*.045f:0;
  voice.hz=hz;voice.volume=volume;voice.boost=boost;voice.whine=whine;voice.slip=slip;cooldown=Mathf.Max(0,cooldown-Time.deltaTime);if(!car.controlsLocked&&car.commandedPedal<=.01f&&cooldown<=0&&PopAllowed(build,car.Engine.Rpm,previousLoad,0,grounded)){popLength=rate/(build.soundStage==2?4:7);popGain=build.soundStage==2?.24f:.18f;voice.popLength=popLength;voice.popGain=popGain;voice.popSamples=popLength;PopCount++;cooldown=build.soundStage==2?.18f:.35f;if(build.sound=="flame"){flame.enabled=true;flameVisual.enabled=true;flame.intensity=build.soundStage==2?4:3;flameVisual.transform.localScale=build.soundStage==2?new Vector3(.12f,.10f,.48f):new Vector3(.10f,.08f,.34f);}}if(load>.35f)previousLoad=load;else if(load<.15f)previousLoad=0;if(flame!=null){flame.intensity=Mathf.MoveTowards(flame.intensity,0,Time.deltaTime*18);if(flame.intensity<=0){flame.enabled=false;flameVisual.enabled=false;}}
 }
 void OnDestroy(){if(source!=null)source.Stop();if(soundRoot!=null)Destroy(soundRoot);if(clip!=null)Destroy(clip);if(flame!=null)Destroy(flame.gameObject);if(flameMaterial!=null)Destroy(flameMaterial);}
}
}
